<section class="page-head compact"><div class="container page-head-inner"><div><div class="eyebrow">Player area</div><h1>Booking <em>saya.</em></h1><p>Semua jadwal main yang pernah kamu buat.</p></div><a href="<?= url('fields') ?>" class="btn btn-primary">+ Booking baru</a></div></section>
<section class="section section-light"><div class="container"><div class="table-card"><div class="table-card-head"><h2>Riwayat booking</h2><a class="text-link" href="<?= url('calendar') ?>">Buka kalender →</a></div><?php if ($bookings): ?><div class="responsive-table"><table><thead><tr><th>Lapangan</th><th>Tanggal & waktu</th><th>Total</th><th>Status</th><th>Pembayaran</th><th></th></tr></thead><tbody><?php foreach ($bookings as $booking): ?><tr><td><strong><?= e($booking['field_name']) ?></strong><small><?= e($booking['location']) ?>, <?= e($booking['city']) ?></small></td><td><?= formatDateId($booking['booking_date']) ?><small><?= substr($booking['start_time'], 0, 5) ?>–<?= substr($booking['end_time'], 0, 5) ?></small></td><td><?= formatRupiah($booking['total_price']) ?></td><td><span class="badge <?= statusClass($booking['status']) ?>"><?= statusLabel($booking['status']) ?></span></td><td><?php if (($booking['payment_status'] ?? '') === 'paid'): ?><span class="badge badge-success">Lunas</span><?php elseif (in_array($booking['status'], ['pending', 'confirmed'], true)): ?><a class="btn-link" href="<?= url('payment/checkout', ['id' => $booking['id']]) ?>">Bayar sekarang</a><?php else: ?><span class="muted">—</span><?php endif; ?></td><td><?php if (in_array($booking['status'], ['pending', 'confirmed'], true)): ?><form method="post" action="<?= url('booking/cancel') ?>" onsubmit="return confirm('Batalkan booking ini?')"><input type="hidden" name="_csrf" value="<?= csrf_token() ?>"><input type="hidden" name="id" value="<?= e($booking['id']) ?>"><button class="btn-link danger" type="submit">Batalkan</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state compact-empty"><div class="empty-icon">◌</div><h3>Belum ada booking</h3><p>Temukan lapangan, pilih slot, lalu buat jadwal main pertamamu.</p><a href="<?= url('fields') ?>" class="btn btn-dark">Cari lapangan</a></div><?php endif; ?></div></div></section>
